async () => {
  const b64 = "";
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const file = new File([bytes], "cane-like-accept.jpg", { type: "image/jpeg" });
  const inputs = [...document.querySelectorAll('input[type=file]'), ...(window.__cgInputs || [])];
  const input = inputs.find((el) => el.type === "file");
  if (!input) return { ok: false, reason: "no-file-input" };
  const dt = new DataTransfer();
  dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event("change"));
  return { ok: true, count: input.files.length, name: input.files[0] && input.files[0].name };
}
